55	    /**
56	     * Derives the owner's duplicate-detection {@code identityKey}, formatted as
57	     * {@code normalizedTelephone + '|' + email + '|' + householdId} with an empty email segment when
58	     * the owner has no email. This is the same key the create endpoint uses to reject an owner whose
59	     * whole key equals an existing owner's.
60	     */
61	    default @Nullable String identityKey(@Nullable Owner owner) {
62	        if (owner == null) {
63	            return null;
64	        }
65	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
66	        String email = owner.getEmail() == null ? "" : owner.getEmail();
67	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
68	        return telephone + "|" + email + "|" + householdId;
