125	    default @Nullable Integer membershipPoints(@Nullable Owner owner) {
126	        if (owner == null) {
127	            return null;
128	        }
129	        int points = 0;
130	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
131	        if (hasEmail) {
132	            points += 2;
133	        }
134	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
135	        if (noNamesakes) {
136	            points += 1;
137	        }
138	        boolean largeHousehold = owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
139	        if (largeHousehold) {
